package io.mateu.ecdemo1.iaagent.workflow;

import com.fasterxml.jackson.databind.ObjectMapper;
import io.mateu.ecdemo1.iaagent.workflow.application.*;
import io.mateu.ecdemo1.iaagent.workflow.application.WorkflowPorts.*;
import io.mateu.ecdemo1.iaagent.workflow.domain.WorkflowExecution;
import io.mateu.ecdemo1.iaagent.workflow.domain.WorkflowExecution.*;
import io.mateu.ecdemo1.iaagent.workflow.infra.JacksonWorkflowCodec;
import org.junit.jupiter.api.Test;
import java.time.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import static org.junit.jupiter.api.Assertions.*;

class WorkflowAgentRunnerTest {
    final MutableClock clock=new MutableClock();
    final ObjectMapper mapper=new ObjectMapper();final Codec codec=new JacksonWorkflowCodec(mapper);final Memory store=new Memory();
    final Map<String,Object> schema=Map.of("type","object","properties",Map.of("decision",Map.of("type","string","enum",List.of("accepted","review"))),"required",List.of("decision"),"additionalProperties",false);
    final Snapshot snapshot=new Snapshot("root","frozen","revision",Map.of("assessor",new Agent("assessor","System",schema),"peer",new Agent("peer","Peer",schema)));
    final Catalogue catalogue=new Catalogue(){public Snapshot resolve(Request r,String d){return snapshot;}public Snapshot snapshot(String root){return snapshot;}public void authorize(Request r){}public void usage(String p){}};
    Request request(){return new Request("root","root",null,"task","process","step","assessor","Assess",Map.of("id","case"),null,null,null,"assessment",100000,"actor",List.of(),300000);}
    Round answer(){return new Round(new Message("assistant","{\"decision\":\"accepted\"}",Map.of("provider-extension","keep-me"),List.of(),null,null),"raw",7,3,"model",Map.of("signature","keep"));}
    Round tool(String kind){return new Round(new Message("assistant","",Map.of(),List.of(new ToolCall("call","action","{\"message\":\"Check\"}")),null,null),"raw",2,1,"model",Map.of());}
    WorkflowAgentRunner runner(Model model,ToolFactory tools){var ref=new WorkflowAgentRunner[1];ref[0]=new WorkflowAgentRunner(store,catalogue,model,tools,codec,clock,10,50,(parent,tool)->ref[0].runDelegation(tool.childId));return ref[0];}
    ToolFactory empty(){return r->new Tools(){public List<ToolSpec> definitions(){return List.of();}public String systemContext(){return "";}public ToolOutcome call(ToolSpec s,String a,String k){throw new AssertionError();}public void close(){}};}
    ToolFactory action(AtomicInteger count,boolean fail,String kind){return r->new Tools(){public List<ToolSpec> definitions(){return List.of(new ToolSpec("action","Action","{}",kind,"peer",false));}public String systemContext(){return "";}public ToolOutcome call(ToolSpec s,String a,String k){count.incrementAndGet();if(fail)throw new IllegalStateException("lost connection");return new ToolOutcome.Ok("{\"ok\":true}");}public void close(){}};}
    @Test void completesValidJsonAndDuplicateDoesNotCallModelAgain(){var calls=new AtomicInteger();var runner=runner((root,agent,m,t,deadline)->{calls.incrementAndGet();return answer();},empty());runner.submit(request());runner.runRoot("root");runner.submit(request());runner.runRoot("root");assertTrue(runner.get("root").messages.getFirst().text().contains("\"required\":[\"decision\"]"));assertEquals(1,calls.get());assertEquals(Status.COMPLETED,runner.get("root").status);assertTrue(store.events.values().stream().anyMatch(e->e.payload().contains("assessment")));}
    @Test void changedInputCannotReuseInvocation(){var runner=runner((r,a,m,t,deadline)->answer(),empty());runner.submit(request());var r=request();assertThrows(IllegalArgumentException.class,()->runner.submit(new Request(r.invocationId(),r.rootInvocationId(),null,r.taskExecutionId(),r.processId(),r.stepId(),r.agentRef(),"Changed",r.input(),null,null,null,r.outputVariable(),r.deadlineEpochMillis(),r.initiatingActor(),r.chain(),r.timeoutMillis())));}
    @Test void invalidSchemaFailsWithoutBusinessOutput(){var runner=runner((r,a,m,t,deadline)->new Round(new Message("assistant","{\"decision\":\"invented\"}",Map.of(),List.of(),null,null),"raw",1,1,"m",Map.of()),empty());runner.submit(request());runner.runRoot("root");assertEquals(Status.FAILED,runner.get("root").status);assertNull(runner.get("root").result);}
    @Test void unknownToolResultRequiresReviewAndIsNeverResent(){var models=new AtomicInteger();var tools=new AtomicInteger();var runner=runner((r,a,m,t,deadline)->models.getAndIncrement()==0?tool("mcp"):answer(),action(tools,true,"mcp"));runner.submit(request());runner.runRoot("root");assertEquals(Status.REVIEW_REQUIRED,runner.get("root").status);runner.runRoot("root");assertEquals(1,tools.get());assertEquals(1,models.get());}
    @Test void reviewBindsDigestAndEvidenceThenResumesWithoutRepeatingTool(){var models=new AtomicInteger();var tools=new AtomicInteger();var runner=runner((r,a,m,t,deadline)->models.getAndIncrement()==0?tool("mcp"):answer(),action(tools,true,"mcp"));runner.submit(request());runner.runRoot("root");var execution=runner.get("root");var call=execution.tools.getFirst();assertThrows(IllegalArgumentException.class,()->runner.reconcile("root",call.id,"wrong","{}","ticket","operator"));runner.reconcile("root",call.id,call.digest,"{\"ok\":true}","external ledger confirms write","operator");runner.runRoot("root");assertEquals(Status.COMPLETED,runner.get("root").status);assertEquals(1,tools.get());}
    @Test void reviewWithoutIdentifiedReviewerCannotChangeDurableState(){
        var models=new AtomicInteger();var runner=runner((r,a,m,t,deadline)->models.getAndIncrement()==0?tool("mcp"):answer(),action(new AtomicInteger(),true,"mcp"));
        runner.submit(request());runner.runRoot("root");var before=runner.get("root");var call=before.tools.getFirst();var eventCount=store.events.size();
        for(String reviewer:Arrays.asList(null,"   "))assertThrows(IllegalArgumentException.class,()->runner.reconcile("root",call.id,call.digest,"{}","write confirmed",reviewer));
        var after=runner.get("root");assertEquals(Status.REVIEW_REQUIRED,after.status);assertEquals(before.stateSequence,after.stateSequence);
        assertEquals(ToolStatus.REVIEW_REQUIRED,after.tools.getFirst().status);assertNull(after.tools.getFirst().reviewer);assertNull(after.tools.getFirst().evidence);assertEquals(eventCount,store.events.size());
    }
    @Test void restartAtDispatchedCheckpointRequiresReviewBeforeOpeningTools(){var runner=runner((r,a,m,t,deadline)->answer(),r->{throw new AssertionError("Must inspect ledger first");});var e=runner.submit(request());e.snapshotId="root";e.snapshotDigest="frozen";var tool=new Tool();tool.id="c";tool.status=ToolStatus.DISPATCHED;tool.kind="mcp";e.tools.add(tool);store.save(e);runner.runRoot("root");assertEquals(Status.REVIEW_REQUIRED,runner.get("root").status);}
    @Test void childUsesStableIdentityAndOutputSchema(){var models=new AtomicInteger();var runner=runner((r,a,m,t,deadline)->"assessor".equals(a)&&models.getAndIncrement()==0?tool("a2a"):answer(),action(new AtomicInteger(),false,"a2a"));runner.submit(request());runner.runRoot("root");assertEquals(Status.COMPLETED,runner.get("root").status);var child=store.find(WorkflowAgentRunner.childId("root",1,"call"));assertNotNull(child);assertEquals(Status.COMPLETED,child.status);assertEquals(List.of("assessor"),child.request.chain());}
    @Test void cancelBeforeTaskDeliveryIsDurableAndNoModelIsCalled(){store.requestCancellation("root");var models=new AtomicInteger();var runner=runner((r,a,m,t,deadline)->{models.incrementAndGet();return answer();},empty());runner.submit(request());runner.runRoot("root");assertEquals(Status.CANCELLED,runner.get("root").status);assertEquals(0,models.get());}
    @Test void remoteSchemaReferenceAndDynamicReferenceRejected(){assertThrows(IllegalArgumentException.class,()->codec.validate(Map.of("type","object","$ref","https://example.invalid/schema"),"{}"));assertThrows(IllegalArgumentException.class,()->codec.validate(Map.of("type","object","$dynamicRef","https://example.invalid/schema"),"{}"));}
    @Test void providerMetadataRoundtripsInDurableState()throws Exception{var e=new WorkflowExecution(request(),"digest");e.rounds.add(answer());e.messages.add(answer().assistant());var restored=mapper.readValue(mapper.writeValueAsString(e),WorkflowExecution.class);assertEquals("keep-me",restored.messages.getFirst().metadata().get("provider-extension"));assertEquals("keep",restored.rounds.getFirst().metadata().get("signature"));}
    @Test void rootSessionLockPreventsConcurrentExecution(){store.locked=true;var models=new AtomicInteger();var runner=runner((r,a,m,t,deadline)->{models.incrementAndGet();return answer();},empty());runner.submit(request());runner.runRoot("root");assertEquals(0,models.get());}
    @Test void jsonDigestIgnoresPropertyOrdering(){assertEquals(codec.digest(Map.of("a",1,"b",2)),codec.digest(new LinkedHashMap<>(Map.of("b",2,"a",1))));}
    @Test void exactGlobalCallBudgetAllowsLastCall(){var models=new AtomicInteger();var toolCalls=new AtomicInteger();var ref=new WorkflowAgentRunner[1];ref[0]=new WorkflowAgentRunner(store,catalogue,(r,a,m,t,deadline)->models.getAndIncrement()==0?tool("mcp"):answer(),action(toolCalls,false,"mcp"),codec,clock,10,1,(p,t)->ref[0].runDelegation(t.childId));ref[0].submit(request());ref[0].runRoot("root");assertEquals(Status.COMPLETED,ref[0].get("root").status);assertEquals(1,toolCalls.get());}
    @Test void reviewRenewsEffectiveDeadlineAndEmitsExplicitSequencedResume(){var models=new AtomicInteger();var runner=runner((r,a,m,t,deadline)->models.getAndIncrement()==0?tool("mcp"):answer(),action(new AtomicInteger(),true,"mcp"));runner.submit(request());runner.runRoot("root");var before=runner.get("root");var tool=before.tools.getFirst();clock.now=200000;runner.reconcile("root",tool.id,tool.digest,"{}","ledger entry","operator");runner.runRoot("root");var after=runner.get("root");assertEquals(Status.COMPLETED,after.status);assertEquals(before.digest,after.digest);assertTrue(after.stateSequence>before.stateSequence);assertTrue(store.events.values().stream().anyMatch(e->e.payload().contains("\"reviewResolved\":true")));}
    @Test void timeoutReviewConfirmsEffectsThenCancelsWithoutResumingModel(){var models=new AtomicInteger();var runner=runner((r,a,m,t,deadline)->{models.incrementAndGet();return tool("mcp");},action(new AtomicInteger(),true,"mcp"));runner.submit(request());runner.runRoot("root");runner.cancel("root");var tool=runner.get("root").tools.getFirst();runner.reconcile("root",tool.id,tool.digest,"{}","write confirmed","operator");assertEquals(Status.CANCELLED,runner.get("root").status);runner.runRoot("root");assertEquals(1,models.get());}
    @Test void childSchemaViolationFailsParentWithoutUncertainReview(){var models=new AtomicInteger();var runner=runner((r,a,m,t,deadline)->"assessor".equals(a)&&models.getAndIncrement()==0?tool("a2a"):new Round(new Message("assistant","{\"decision\":\"invalid\"}",Map.of(),List.of(),null,null),"raw",1,1,"model",Map.of()),action(new AtomicInteger(),false,"a2a"));runner.submit(request());runner.runRoot("root");assertEquals(Status.FAILED,runner.get("root").status);}
    @Test void childReviewPropagatesAndCancellationReconcilesBottomUp(){var models=new AtomicInteger();var runner=runner((r,a,m,t,deadline)->"assessor".equals(a)&&models.getAndIncrement()==0?tool("a2a"):tool("mcp"),r->"assessor".equals(r.agentRef())?action(new AtomicInteger(),false,"a2a").open(r):action(new AtomicInteger(),true,"mcp").open(r));runner.submit(request());runner.runRoot("root");assertEquals(Status.REVIEW_REQUIRED,runner.get("root").status);var child=runner.get(WorkflowAgentRunner.childId("root",1,"call"));assertEquals(Status.REVIEW_REQUIRED,child.status);assertTrue(runner.list().stream().anyMatch(e->e.request.invocationId().equals(child.request.invocationId())&&e.tools.stream().anyMatch(t->t.status==ToolStatus.REVIEW_REQUIRED)));runner.cancel("root");var tool=child.tools.getFirst();runner.reconcile(child.request.invocationId(),tool.id,tool.digest,"{}","remote operation reconciled","operator");assertEquals(Status.CANCELLED,runner.get(child.request.invocationId()).status);assertEquals(Status.CANCELLED,runner.get("root").status);}
    @Test void a2aPayloadMutationCannotReusePersistedChild(){var models=new AtomicInteger();var runner=runner((r,a,m,t,deadline)->"assessor".equals(a)&&models.getAndIncrement()==0?tool("a2a"):answer(),action(new AtomicInteger(),false,"a2a"));runner.submit(request());runner.runRoot("root");assertThrows(IllegalArgumentException.class,()->runner.acceptDelegation("peer","root","call",Map.of("message","changed")));assertEquals(Status.COMPLETED,runner.acceptDelegation("peer","root","call",Map.of("message","Check")).status);}
    @Test void a2aInfrastructureOutageRemainsRecoverableWithoutFalseHumanHold(){
        var modelCalls=new AtomicInteger();var sends=new AtomicInteger();var ref=new WorkflowAgentRunner[1];
        ref[0]=new WorkflowAgentRunner(store,catalogue,(r,a,m,t,deadline)->"assessor".equals(a)&&modelCalls.getAndIncrement()==0?tool("a2a"):answer(),action(new AtomicInteger(),false,"a2a"),codec,clock,10,50,(parent,tool)->{if(sends.getAndIncrement()==0)throw new IllegalStateException("catalogue unavailable before child transport");ref[0].runDelegation(tool.childId);});
        ref[0].submit(request());ref[0].runRoot("root");assertEquals(Status.RUNNING,ref[0].get("root").status);ref[0].runRoot("root");assertEquals(Status.COMPLETED,ref[0].get("root").status);assertEquals(2,store.children("root").size());
    }
    /** Each call consumes the next scripted outcome; a RuntimeException entry is thrown as an uncertain failure. */
    ToolFactory scripted(AtomicInteger count,boolean readOnly,String schema,Object... outcomes){return r->new Tools(){public List<ToolSpec> definitions(){return List.of(new ToolSpec("action","Action",schema,"mcp","peer",readOnly));}public String systemContext(){return "";}public ToolOutcome call(ToolSpec s,String a,String k){var next=outcomes[Math.min(count.getAndIncrement(),outcomes.length-1)];if(next instanceof RuntimeException ex)throw ex;return (ToolOutcome)next;}public void close(){}};}
    Round toolCall(String id,String name,String args){return new Round(new Message("assistant","",Map.of(),List.of(new ToolCall(id,name,args)),null,null),"raw",2,1,"model",Map.of());}
    Model rounds(AtomicInteger models,Round... script){return (r,a,m,t,deadline)->script[Math.min(models.getAndIncrement(),script.length-1)];}
    @Test void rejectedToolReturnsToModelAndRetryCompletes(){var models=new AtomicInteger();var sends=new AtomicInteger();var seen=new ArrayList<List<Message>>();
        var runner=runner((r,a,m,t,deadline)->{seen.add(m);return switch(models.getAndIncrement()){case 0->toolCall("c1","action","{}");case 1->toolCall("c2","action","{}");default->answer();};},scripted(sends,false,"{}",new ToolOutcome.Rejected("quota exceeded","tool_error",false),new ToolOutcome.Ok("{\"ok\":true}")));
        runner.submit(request());runner.runRoot("root");var e=runner.get("root");assertEquals(Status.COMPLETED,e.status);assertEquals(2,sends.get());
        assertTrue(e.tools.getFirst().error);assertEquals(ToolStatus.CONFIRMED,e.tools.getFirst().status);assertTrue(seen.get(1).getLast().text().contains("quota exceeded"));assertFalse(e.tools.get(1).error);}
    @Test void unregisteredToolIsReportedToModelWithoutDispatch(){var models=new AtomicInteger();var sends=new AtomicInteger();var runner=runner(rounds(models,toolCall("c1","missing","{}"),answer()),scripted(sends,false,"{}",new ToolOutcome.Ok("{}")));
        runner.submit(request());runner.runRoot("root");var e=runner.get("root");assertEquals(Status.COMPLETED,e.status);assertEquals(0,sends.get());assertTrue(e.tools.getFirst().result.contains("unregistered_tool"));assertFalse(e.tools.getFirst().sent);}
    @Test void invalidArgumentsAreNeverSent(){var models=new AtomicInteger();var sends=new AtomicInteger();var schema="{\"type\":\"object\",\"properties\":{\"id\":{\"type\":\"string\"}},\"required\":[\"id\"]}";
        var runner=runner(rounds(models,toolCall("c1","action","{}"),toolCall("c2","action","not json"),toolCall("c3","action","{\"id\":\"x\"}"),answer()),scripted(sends,false,schema,new ToolOutcome.Ok("{}")));
        runner.submit(request());runner.runRoot("root");var e=runner.get("root");assertEquals(Status.COMPLETED,e.status);assertEquals(1,sends.get());assertTrue(e.tools.get(0).result.contains("invalid_arguments"));assertTrue(e.tools.get(1).result.contains("invalid_arguments"));}
    @Test void readOnlyTransportFailureBecomesTransientError(){var models=new AtomicInteger();var sends=new AtomicInteger();var runner=runner(rounds(models,toolCall("c1","action","{}"),toolCall("c2","action","{}"),answer()),scripted(sends,true,"{}",new IllegalStateException("timeout"),new ToolOutcome.Ok("{}")));
        runner.submit(request());runner.runRoot("root");var e=runner.get("root");assertEquals(Status.COMPLETED,e.status);assertEquals(2,sends.get());assertTrue(e.tools.getFirst().result.contains("\"transient\":true"));}
    @Test void effectfulTransportFailureStillRequiresReview(){var models=new AtomicInteger();var sends=new AtomicInteger();var runner=runner(rounds(models,toolCall("c1","action","{}"),answer()),scripted(sends,false,"{}",new IllegalStateException("timeout")));
        runner.submit(request());runner.runRoot("root");assertEquals(Status.REVIEW_REQUIRED,runner.get("root").status);runner.runRoot("root");assertEquals(1,sends.get());assertEquals(1,models.get());}
    @Test void toolErrorLimitFailsTheStep(){var models=new AtomicInteger();var sends=new AtomicInteger();var ref=new WorkflowAgentRunner[1];
        ref[0]=new WorkflowAgentRunner(store,catalogue,(r,a,m,t,deadline)->toolCall("c"+models.getAndIncrement(),"action","{}"),scripted(sends,false,"{}",new ToolOutcome.Rejected("boom","tool_error",false)),codec,clock,10,50,2,(p,t)->ref[0].runDelegation(t.childId));
        ref[0].submit(request());ref[0].runRoot("root");var e=ref[0].get("root");assertEquals(Status.FAILED,e.status);assertTrue(e.error.contains("Tool error limit exceeded"));assertEquals(3,sends.get());}
    @Test void resumeAfterRejectionDoesNotResend(){var models=new AtomicInteger();var sends=new AtomicInteger();var ref=new WorkflowAgentRunner[1];var crash=new AtomicInteger();
        ref[0]=new WorkflowAgentRunner(store,catalogue,(r,a,m,t,deadline)->{if(models.getAndIncrement()==0)return toolCall("c1","action","{}");if(crash.getAndIncrement()==0)throw new DelegationUnavailable("worker stopped");return answer();},scripted(sends,false,"{}",new ToolOutcome.Rejected("no","tool_error",false)),codec,clock,10,50,5,(p,t)->ref[0].runDelegation(t.childId));
        ref[0].submit(request());ref[0].runRoot("root");assertEquals(Status.RUNNING,ref[0].get("root").status);ref[0].runRoot("root");var e=ref[0].get("root");assertEquals(Status.COMPLETED,e.status);assertEquals(1,sends.get());assertTrue(e.tools.getFirst().error);}
    @Test void rejectedBeforeSendDoesNotConsumeCallBudget(){var models=new AtomicInteger();var sends=new AtomicInteger();var ref=new WorkflowAgentRunner[1];
        ref[0]=new WorkflowAgentRunner(store,catalogue,rounds(models,toolCall("c1","missing","{}"),toolCall("c2","action","{}"),answer()),scripted(sends,false,"{}",new ToolOutcome.Ok("{}")),codec,clock,10,1,5,(p,t)->ref[0].runDelegation(t.childId));
        ref[0].submit(request());ref[0].runRoot("root");assertEquals(Status.COMPLETED,ref[0].get("root").status);assertEquals(1,sends.get());}
    @Test void legacyToolRowWithoutNewFieldsDeserializes()throws Exception{var t=mapper.readValue("{\"id\":\"c\",\"status\":\"CONFIRMED\",\"readOnly\":false}",Tool.class);assertFalse(t.error);assertFalse(t.sent);}
    static class MutableClock extends Clock {long now=1000;public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return Instant.ofEpochMilli(now);}public long millis(){return now;}}
    class Memory implements Store {
        final Map<String,WorkflowExecution> rows=new LinkedHashMap<>();final Map<String,Outbox> events=new LinkedHashMap<>();final Set<String> cancels=new HashSet<>();boolean locked;final Set<String> locks=new HashSet<>();
        WorkflowExecution copy(WorkflowExecution e){try{return mapper.readValue(mapper.writeValueAsString(e),WorkflowExecution.class);}catch(Exception x){throw new RuntimeException(x);}}
        public WorkflowExecution find(String id){return rows.containsKey(id)?copy(rows.get(id)):null;}
        public WorkflowExecution create(WorkflowExecution e){if(rows.containsKey(e.request.invocationId())&&!rows.get(e.request.invocationId()).digest.equals(e.digest))throw new IllegalArgumentException("conflict");rows.putIfAbsent(e.request.invocationId(),copy(e));return find(e.request.invocationId());}
        public void save(WorkflowExecution e){e.stateSequence++;rows.put(e.request.invocationId(),copy(e));}
        public List<String> pendingRoots(){return rows.keySet().stream().toList();}public List<WorkflowExecution> roots(){return rows.values().stream().filter(e->e.request.parentInvocationId()==null).map(this::copy).toList();}
        public List<WorkflowExecution> children(String id){return rows.values().stream().filter(e->e.request.rootInvocationId().equals(id)).map(this::copy).toList();}
        public AutoCloseable lock(String id){if(locked||!locks.add(id))return null;return ()->locks.remove(id);}
        public void outbox(String id,String kind,String payload){events.putIfAbsent(id,new Outbox(id,kind,payload));}public List<Outbox> pendingOutbox(){return List.copyOf(events.values());}public void delivered(String id){events.remove(id);}
        public void requestCancellation(String id){cancels.add(id);}public boolean cancellationRequested(String id){return cancels.contains(id);}
    }
}
